/* Defensive: same protection if an older Site-Editor-saved header is still in
   the database (without the .cs- classes on the search/button blocks). */
.cs-main-nav {
  min-width: 0;
}

.cs-site-header .wp-block-buttons,
.cs-header .wp-block-buttons {
  flex: 0 0 auto;
}

.cs-site-header .wp-block-button__link,
.cs-header .wp-block-button__link {
  white-space: nowrap;
  word-break: normal;
  overflow-wrap: normal;
}

.cs-site-header .wp-block-site-title,
.cs-header .wp-block-site-title {
  white-space: nowrap;
}

.cs-site-header .wp-block-search,
