/* ---- Main navigation: labels ALWAYS visible (this was the hover bug) ---- */
.cs-main-nav {
  opacity: 1 !important;
  visibility: visible !important;
  /* Neutralise the old global `ul{display:table-cell}` style inside the menu */
  /* Desktop dropdown */
  /* Mobile-only CTA links: hidden in the desktop bar, shown inside the overlay */
  /* Hamburger & close buttons (printed by WP core as inline SVG) */
}
.cs-main-nav ul {
  display: flex;
  width: auto;
  max-width: none;
  margin: 0;
  padding: 0 !important;
  list-style: none;
}
