  display: none !important;
}
.cs-main-nav .wp-block-navigation-item__content,
.cs-main-nav .wp-block-navigation-item__label {
  color: #0b1226 !important;
  opacity: 1 !important;
  visibility: visible !important;
}
.cs-main-nav .wp-block-navigation-item__content {
  padding: 0.9rem 1.1rem;
  border-radius: 0.9rem;
  font-weight: 700;
  font-size: 1.6rem;
  line-height: 1.2;
  text-decoration: none !important;
  white-space: nowrap;
}
.cs-main-nav .wp-block-navigation-item__content:hover, .cs-main-nav .wp-block-navigation-item__content:focus-visible {
  background: #ecfeff;
