  color: #0b1226;
}
.cs-main-nav .wp-block-navigation__submenu-container {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 1.2rem;
  box-shadow: 0 1.8rem 4rem rgba(2, 6, 23, 0.14);
  padding: 0.8rem;
  min-width: 24rem;
  z-index: 1001;
}
.cs-main-nav .wp-block-navigation__submenu-container .wp-block-navigation-item__content {
  white-space: normal;
}
.cs-main-nav .cs-nav-mobile-cta {
  display: none;
}
.cs-main-nav .wp-block-navigation__responsive-container-open,
.cs-main-nav .wp-block-navigation__responsive-container-close {
  align-items: center;
  justify-content: center;
  width: 4.6rem;
  height: 4.6rem;
