}
.cs-main-nav .wp-block-navigation__responsive-container-open svg,
.cs-main-nav .wp-block-navigation__responsive-container-close svg {
  width: 2.6rem;
  height: 2.6rem;
}
.cs-main-nav .wp-block-navigation__responsive-container-open {
