/* Desktop >= 1200px : inline menu, no hamburger (WP default, stated explicitly) */
@media (min-width: 1200px) {
  .cs-main-nav .wp-block-navigation__responsive-container-open {
    display: none !important;
  }
  .cs-main-nav .wp-block-navigation__responsive-container {
    position: static;
    opacity: 1;
    visibility: visible;
  }
}
/* Search only when there is real room for it (incl. old-DB headers whose
   search block lacks the .cs-header-search class) */
@media (max-width: 1399px) {
  .cs-header-search,
  .cs-site-header .wp-block-search,
