/* Tablet + Mobile <= 1199px : hamburger + full-screen overlay (WP core) */
@media (max-width: 1199px) {
  .cs-mobile-wa {
    display: inline-flex;
  }
  .cs-main-nav {
    margin-left: auto;
    /* THE switch: hide the inline list until WP adds .is-menu-open */
    /* Submenus inside the overlay: static indented list, always readable */
  }
  .cs-main-nav .wp-block-navigation__responsive-container-open {
    display: inline-flex !important;
  }
  .cs-main-nav .wp-block-navigation__responsive-container:not(.is-menu-open) {
    display: none !important;
  }
  .cs-main-nav .wp-block-navigation__responsive-container.is-menu-open {
    display: flex;
    position: fixed;
    inset: 0;
    z-index: 100000;
    background: #0b1226;
    color: #fff;
    padding: 2rem;
