/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .cs-inner-layout,
  .cs-inner--lab .cs-inner-layout,
  .cs-inner--focus .cs-inner-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .cs-inner-sidebar {
    position: static;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  body.admin-bar .cs-inner-sidebar {
    top: auto;
  }
  .cs-inner-article {
    padding: clamp(2rem, 4vw, 3.2rem);
  }
}
@media (max-width: 767px) {
  .cs-inner-hero {
    padding-top: 2.8rem;
  }
  .cs-inner-title {
    font-size: clamp(3.1rem, 10vw, 4.2rem) !important;
  }
  .cs-inner-article {
    border-radius: 2rem;
    padding: 2rem 1.7rem;
  }
  .cs-inner-content {
    font-size: 1.66rem;
    line-height: 1.74;
  }
  .cs-inner-content h2, .cs-inner-content .h2 {
    margin-top: 3rem;
  }
  .cs-inner-sidebar {
    grid-template-columns: minmax(0, 1fr);
  }
  .cs-inner-meta p, .cs-inner-meta .wp-block-understrap-tabs .nav .nav-link .tab-nav-content .tab-nav-description, .wp-block-understrap-tabs .nav .nav-link .tab-nav-content .cs-inner-meta .tab-nav-description,
  .cs-inner-meta time,
  .cs-inner-meta .wp-block-post-date {
    font-size: 1.2rem;
  }
  .cs-inner-hero-media img,
  .cs-inner-article-media img {
    border-radius: 1.6rem;
    max-height: 28rem;
  }
  .cs-inner-btn {
    width: 100%;
    box-sizing: border-box;
  }
}
@media (max-width: 420px) {
  .cs-side-card,
  .cs-callout,
  .cs-summary {
    padding: 1.7rem;
  }
  .cs-inner-content table {
    min-width: 46rem;
  }
  .cs-inner-title {
    letter-spacing: -0.02em;
  }
}
